    Bug 242300 - Improve the visibility of unread child messages in a collapsed thread. r=laurel,arschmitz


    #### How to test

    - Set the message list in Table View.
    - Open a thread and mark a child message as `unread`.
    - Close the thread, and select another message.

    Differential Revision: https://phabricator.services.mozilla.com/D278355

diff --git a/mail/themes/shared/mail/threadPane.css b/mail/themes/shared/mail/threadPane.css
index b2b39291f45..592e48ce738 100644
--- a/mail/themes/shared/mail/threadPane.css
+++ b/mail/themes/shared/mail/threadPane.css
@@ -90,8 +90,20 @@
     }
   }

-  & .table-layout.children.collapsed[data-properties~="hasUnread"][data-properties~="read"] :where(td, .subject-line) {
-    text-decoration: underline;
+  & .table-layout.children.collapsed[data-properties~="hasUnread"][data-properties~="read"] {
+    & :where(td, .subject-line) {
+      font-weight: 600;
+      text-decoration: underline;
+    }
+
+    :not(.selected) & .tree-button-unread img {
+      fill: transparent;
+      stroke: var(--primary);
+    }
+
+    & .tree-button-unread img {
+      stroke: currentColor;
+    }
   }

   & [data-properties~="ignore"] .tree-view-row-thread img {
diff --git a/mail/themes/shared/mail/tree-listbox.css b/mail/themes/shared/mail/tree-listbox.css
index 71601f0dc42..a75ef524ce3 100644
--- a/mail/themes/shared/mail/tree-listbox.css
+++ b/mail/themes/shared/mail/tree-listbox.css
@@ -444,6 +444,10 @@ th[is="tree-view-table-header-cell"] {
       content: var(--icon-column-menu);
       margin-inline: 0;
     }
+
+    @media (-moz-overlay-scrollbars) {
+      padding-inline-end: env(scrollbar-inline-size);
+    }
   }

   &.last-column:not(.column-dragging, .column-moved-by-dragging) .button-column-picker {
